<?php
declare(strict_types=1);require_once __DIR__.'/../_admin.php';header('Cache-Control: no-store');$input=adminMethod(['GET','POST']);$pdo=Database::getInstance();[$session,$role]=requireAdmin($pdo,$input);requireAdminRole($role,['super_admin','finance'],'manage promo codes');
if($_SERVER['REQUEST_METHOD']==='POST'){$action=(string)($input['action']??'');$uuid=trim((string)($input['uuid']??''));if($action==='set_status'){if(!preg_match('/^[a-f0-9-]{36}$/i',$uuid)||!in_array($input['status']??'', ['active','paused'],true))jsonResponse(['success'=>false,'error'=>'Invalid promo status request.'],422);$stmt=$pdo->prepare('UPDATE promo_codes SET status=?,updated_by=? WHERE uuid=?');$stmt->execute([(string)$input['status'],(int)$session['admin']['id'],$uuid]);if(!$stmt->rowCount())jsonResponse(['success'=>false,'error'=>'Promo code not found.'],404);adminAudit($pdo,(int)$session['admin']['id'],'admin.promo_status_changed','promo_code',$uuid,['status'=>$input['status']]);jsonResponse(['success'=>true,'message'=>'Promo code status updated.']);}
 if(!in_array($action,['create','update'],true))jsonResponse(['success'=>false,'error'=>'Unknown promo action.'],422);$code=strtoupper(trim((string)($input['code']??'')));$type=(string)($input['type']??'');$title=trim((string)($input['title']??''));$value=$input['value']??null;$audience=(string)($input['audience']??'all');if(!preg_match('/^[A-Z0-9_-]{4,20}$/',$code)||$title===''||!in_array($type,['wallet_bonus','cashback','fee_discount','free_transfers'],true)||!is_numeric($value)||(float)$value<0||!in_array($audience,['all','new_users','verified'],true))jsonResponse(['success'=>false,'error'=>'Enter a valid code, name, reward and audience.'],422);if(in_array($type,['cashback','fee_discount'],true)&&(float)$value>100)jsonResponse(['success'=>false,'error'=>'Percent rewards cannot exceed 100.'],422);$start=trim((string)($input['starts_at']??''));$end=trim((string)($input['expires_at']??''));if($start!==''&&$end!==''&&$end<$start)jsonResponse(['success'=>false,'error'=>'The end date must be after the start date.'],422);$values=[$code,$title,$type,(string)$value,$input['max_reward']?:null,$input['min_amount']?:null,$audience,$input['usage_limit']?:null,max(1,(int)($input['per_user_limit']??1)),$start?:null,$end?:null];if($action==='create'){$uuid=generateUUID();$stmt=$pdo->prepare('INSERT INTO promo_codes(uuid,code,title,reward_type,reward_value,max_reward,min_amount,audience,usage_limit,per_user_limit,starts_at,expires_at,created_by,updated_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$stmt->execute([$uuid,...$values,(int)$session['admin']['id'],(int)$session['admin']['id']]);adminAudit($pdo,(int)$session['admin']['id'],'admin.promo_created','promo_code',$uuid,['code'=>$code]);jsonResponse(['success'=>true,'message'=>'Promo code created.'],201);}if(!preg_match('/^[a-f0-9-]{36}$/i',$uuid))jsonResponse(['success'=>false,'error'=>'Invalid promo reference.'],422);$stmt=$pdo->prepare('UPDATE promo_codes SET code=?,title=?,reward_type=?,reward_value=?,max_reward=?,min_amount=?,audience=?,usage_limit=?,per_user_limit=?,starts_at=?,expires_at=?,updated_by=? WHERE uuid=?');$stmt->execute([...$values,(int)$session['admin']['id'],$uuid]);if(!$stmt->rowCount())jsonResponse(['success'=>false,'error'=>'Promo code not found.'],404);adminAudit($pdo,(int)$session['admin']['id'],'admin.promo_updated','promo_code',$uuid,['code'=>$code]);jsonResponse(['success'=>true,'message'=>'Promo code updated.']);}
$promos=$pdo->query("SELECT p.uuid,p.code,p.title,p.reward_type type,p.reward_value value,p.max_reward,p.min_amount,p.audience,p.usage_limit,p.per_user_limit,p.status,p.starts_at,p.expires_at,p.created_at,COUNT(r.id) used_count FROM promo_codes p LEFT JOIN promo_redemptions r ON r.promo_code_id=p.id AND r.status IN ('qualified','awarded') GROUP BY p.id ORDER BY p.created_at DESC")->fetchAll();$summary=$pdo->query("SELECT COUNT(*) total,COALESCE(SUM(status='active' AND (starts_at IS NULL OR starts_at<=UTC_TIMESTAMP()) AND (expires_at IS NULL OR expires_at>=UTC_TIMESTAMP())),0) active_codes,COALESCE((SELECT COUNT(*) FROM promo_redemptions WHERE status IN ('qualified','awarded')),0) total_redemptions,COALESCE((SELECT SUM(reward_amount) FROM promo_redemptions WHERE status='awarded'),0) rewards_paid,COALESCE(SUM(status='active' AND expires_at BETWEEN UTC_TIMESTAMP() AND DATE_ADD(UTC_TIMESTAMP(),INTERVAL 7 DAY)),0) expiring_soon FROM promo_codes")->fetch()?:[];jsonResponse(['success'=>true,'promos'=>$promos,'summary'=>['active_codes'=>(int)$summary['active_codes'],'total_redemptions'=>(int)$summary['total_redemptions'],'rewards_paid'=>(string)$summary['rewards_paid'],'expiring_soon'=>(int)$summary['expiring_soon']]]);
